1	package txsaga
2	
3	import (
4		"context"
5		"strings"
6		"sync"
7		"time"
8	)
9	
10	// ValidateDefinition 校验 Saga 定义，非法时返回 ErrInvalidDefinition（可 errors.Is）。
11	// 规则：名称非空、至少一个步骤、每个步骤名非空且不重复、每个步骤都提供正向
12	// 动作；任一动作/补偿的重试最大总调用次数为负、失败等待时长为负同样非法。
13	// 未配置的重试预算按最大 1 次、等待 0 处理。
14	func ValidateDefinition(d Definition) error {
15		if strings.TrimSpace(d.Name) == "" {
16			return ErrInvalidDefinition
17		}
18		if len(d.Steps) == 0 {
19			return ErrInvalidDefinition
20		}
21		seen := make(map[string]struct{}, len(d.Steps))
22		for _, st := range d.Steps {
23			if strings.TrimSpace(st.Name) == "" || st.Action == nil {
24				return ErrInvalidDefinition
25			}
26			if _, dup := seen[st.Name]; dup {
27				return ErrInvalidDefinition
28			}
29			if st.ActionRetry.MaxAttempts < 0 || st.ActionRetry.RetryWait < 0 ||
30				st.CompensateRetry.MaxAttempts < 0 || st.CompensateRetry.RetryWait < 0 {
31				return ErrInvalidDefinition
32			}
33			seen[st.Name] = struct{}{}
34		}
35		return nil
36	}
37	
38	// Engine 在给定 Store 上执行 Saga。零值不可用，请用 NewEngine 创建。
39	type Engine struct {
40		store Store
41	
42		// 同执行身份的进程内串行化，避免并发调用重复进入同一未确认动作。
43		locksMu sync.Mutex
44		locks   map[string]*sync.Mutex
45	
46		// now 为可注入时钟；生产使用 time.Now。
47		now func() time.Time
48	}
49	
50	// NewEngine 创建基于 store 的编排引擎。
51	func NewEngine(store Store) *Engine {
52		return &Engine{store: store, locks: make(map[string]*sync.Mutex), now: time.Now}
53	}
54	
55	func (e *Engine) identityLock(businessKey, idempotencyKey string) *sync.Mutex {
56		key := businessKey + "\x00" + idempotencyKey
57		e.locksMu.Lock()
58		m, ok := e.locks[key]
59		if !ok {
60			m = &sync.Mutex{}
61			e.locks[key] = m
62		}
63		e.locksMu.Unlock()
64		return m
65	}
66	
67	type execView struct {
68		state   *ExecutionState
69		payload any
70	}
71	
72	func (v execView) BusinessKey() string    { return v.state.BusinessKey }
73	func (v execView) SagaName() string       { return v.state.SagaName }
74	func (v execView) IdempotencyKey() string { return v.state.IdempotencyKey }
75	func (v execView) Payload() any           { return v.payload }
76	
77	func (v execView) SucceededSteps() []string {
78		var names []string
79		for _, st := range v.state.Steps {
80			if st.Status == StepResultSucceeded {
81				names = append(names, st.Name)
82			}
83		}
84		return names
85	}
86	
87	// Execute 按 Definition 执行一次 Saga 请求。
88	//
89	// 执行身份由业务键、Saga 定义与外部幂等键共同确定：
90	//   - 新身份：创建执行并顺序执行未完成步骤；
91	//   - 同身份重试：不重复执行已确认成功的正向步骤或补偿步骤；
92	//     结果未确认的步骤允许被重新调用，重入次数累计在对应步骤的 Attempts，
93	//     动作自身须遵守幂等契约；
94	//   - 已到达终态：直接返回固定的终态结果，不再调用任何动作，也不再追加事件；
95	//   - 同业务键绑定不同定义：返回 ErrDefinitionConflict；
96	//   - 非法定义或缺失业务键/幂等键：返回 ErrInvalidDefinition。
97	//
98	// 每一步确认后，状态与对应 Outbox 事件在同一个 Store 事务中原子提交，
99	// 然后才执行下一步。正向动作在其 ActionRetry 预算内的失败会在指定等待后
100	// 重试同一动作，中间失败不提交状态、不追加事件；预算耗尽仍失败才停止推进，
101	// 仅逆序补偿此前确认成功的步骤。补偿动作同样可配置 CompensateRetry 预算，
102	// 预算耗尽仍报错则固定为 compensation_failed 终态。重试等待与动作本身都
103	// 响应 ctx：ctx 取消时 Execute 返回 ctx 的错误，不确认当前动作、不启动补偿，
104	// 也不改变已经提交的执行状态。
105	func (e *Engine) Execute(ctx context.Context, def Definition, req ExecutionRequest) (Result, error) {
106		if err := ValidateDefinition(def); err != nil {
107			return Result{}, err
108		}
109		if strings.TrimSpace(req.BusinessKey) == "" || strings.TrimSpace(req.IdempotencyKey) == "" {
110			return Result{}, ErrInvalidDefinition
111		}
112		fp := fingerprint(def)
113	
114		mu := e.identityLock(req.BusinessKey, req.IdempotencyKey)
115		mu.Lock()
116		defer mu.Unlock()
117	
118		for {
119			if err := ctx.Err(); err != nil {
120				return Result{}, err
121			}
122			snap, err := e.store.LoadSnapshot(ctx, req.BusinessKey, req.IdempotencyKey)
123			if err != nil {
124				return Result{}, err
125			}
126			if snap.Bound && snap.Binding.Fingerprint != fp {
127				return Result{}, ErrDefinitionConflict
128			}
129			st := snap.State
130			if st == nil {
131				if err := e.createExecution(ctx, def, fp, req); err != nil {
132					return Result{}, err
133				}
134				continue
135			}
136			if st.Fingerprint != fp {
137				return Result{}, ErrDefinitionConflict
138			}
139			if st.Terminal() {
140				return toResult(st), nil
141			}
142	
143			switch st.Status {
144			case StatusRunning:
145				advanced, err := e.advanceForward(ctx, def, req, st)
146				if err != nil {
147					return Result{}, err
148				}
149				if !advanced {
150					// 所有步骤均已确认成功，重新读取以取得 completed 终态。
151					snap2, err := e.store.LoadSnapshot(ctx, req.BusinessKey, req.IdempotencyKey)
152					if err != nil {
153						return Result{}, err
154					}
155					return toResult(snap2.State), nil
156				}
157			case StatusCompensating:
158				done, err := e.advanceCompensation(ctx, def, req, st)
159				if err != nil {
160					return Result{}, err
161				}
162				if done {
163					return e.finishFailed(ctx, req)
164				}
165			default:
166				return Result{}, ErrInvalidDefinition
167			}
168		}
169	}
170	
171	// createExecution 在一个原子事务中建立执行状态并追加 started 事件。
172	func (e *Engine) createExecution(ctx context.Context, def Definition, fp string, req ExecutionRequest) error {
173		return e.store.Commit(ctx, req.BusinessKey, req.IdempotencyKey, func(tx Tx) error {
174			if b, ok := tx.Binding(); ok && b.Fingerprint != fp {
175				return ErrDefinitionConflict
176			}
177			if tx.State() != nil {
178				return nil // 并发情况下已由其它调用建立，直接沿用
179			}
180			steps := make([]StepState, len(def.Steps))
181			for i, s := range def.Steps {
182				steps[i] = StepState{Name: s.Name}
183			}
184			tx.Create(&ExecutionState{
185				SagaName:    def.Name,
186				Fingerprint: fp,
187				Status:      StatusRunning,
188				Steps:       steps,
189				Payload:     req.Payload,
190			})
191			tx.AppendEvent(EventExecutionStarted, EventPayload{
192				SagaName:       def.Name,
193				IdempotencyKey: req.IdempotencyKey,
194				Status:         StatusRunning,
195			})
196			return nil
197		})
198	}
199	
200	// advanceForward 执行下一个未完成的正向步骤，在事务外调用动作，再把
201	// 成功/失败结果与事件原子提交。返回 false 表示已无待执行步骤。
202	//
203	// 步骤配置了 ActionRetry 时，动作在预算内失败会等待指定时长后再次调用同一
204	// 动作；中间失败既不提交状态也不追加事件。等待与动作都响应 ctx：ctx 取消
205	// 时直接返回其错误，本次不确认动作、不启动补偿，已提交的步骤状态保持不变。
206	func (e *Engine) advanceForward(ctx context.Context, def Definition, req ExecutionRequest, st *ExecutionState) (bool, error) {
207		idx := -1
208		for i := range st.Steps {
209			if st.Steps[i].Status == "" {
210				idx = i
211				break
212			}
213		}
214		if idx < 0 {
215			return false, nil
216		}
217		step := def.Steps[idx]
218	
219		// Attempts 记录本阶段（含预算内重试）动作的实际调用次数，成功或预算
220		// 耗尽后随状态一次提交；未确认的中间失败不会留下任何计数。
221		startedAt := e.now()
222		actionErr, attempts, err := e.runWithRetry(ctx, step.ActionRetry, func() error {
223			return step.Action(ctx, execView{state: st, payload: req.Payload})
224		})
225		if err != nil {
226			// 调用方取消（等待期间或动作随 ctx 结束）：不解释为业务失败，
227			// 未确认的步骤留待后续同身份重试，已确认的提交状态不变。
228			return false, err
229		}
230		finishedAt := e.now()
231		st.Steps[idx].Attempts = attempts
232		st.Steps[idx].StartedAt = startedAt
233	
234		err = e.store.Commit(ctx, req.BusinessKey, req.IdempotencyKey, func(tx Tx) error {
235			cur := tx.State()
236			if cur == nil || cur.Terminal() {
237				return nil // 状态已被其它路径推进，本次结果丢弃
238			}
239			cs := &cur.Steps[idx]
240			cs.Attempts = attempts
241			cs.StartedAt = startedAt
242			cs.FinishedAt = finishedAt
243	
244			if actionErr == nil {
245				cs.Status = StepResultSucceeded
246				cs.LastError = ""
247				succeeded := succeededNames(cur)
248				if idx == len(cur.Steps)-1 {
249					cur.Status = StatusCompleted
250					tx.AppendEvent(EventStepSucceeded, stepEvent(def, req, step.Name, StatusCompleted, succeeded))
251					tx.AppendEvent(EventExecutionCompleted, EventPayload{
252						SagaName:       def.Name,
253						IdempotencyKey: req.IdempotencyKey,
254						Status:         StatusCompleted,
255						SucceededSteps: succeeded,
256					})
257				} else {
258					cur.Status = StatusRunning
259					tx.AppendEvent(EventStepSucceeded, stepEvent(def, req, step.Name, StatusRunning, succeeded))
260				}
261				return nil
262			}
263	
264			errMsg := actionErr.Error()
265			cs.Status = StepResultFailed
266			cs.LastError = errMsg
267			cur.FailedStep = step.Name
268			cur.FailureReason = errMsg
269			cur.Status = StatusCompensating
270			tx.AppendEvent(EventStepFailed, EventPayload{
271				SagaName:       def.Name,
272				IdempotencyKey: req.IdempotencyKey,
273				Step:           step.Name,
274				Status:         StatusCompensating,
275				Reason:         errMsg,
276				SucceededSteps: succeededNames(cur),
277			})
278			return nil
279		})
280		return err == nil, err
281	}
282	
283	// runWithRetry 在重试预算内反复调用同一动作。
284	//
285	// 返回 actionErr 为 nil 表示预算内成功（调用次数计入 attempts）；
286	// actionErr 非 nil、err 为 nil 表示预算耗尽仍失败，actionErr 为最近一次错误；
287	// err 非 nil 表示外层 context 已取消——可能发生在调用前、失败后的等待期间，
288	// 也可能动作刚返回（无论它返回 nil 还是错误），只要外层 context 已取消就
289	// 按取消处理：不确认动作，由调用方原样返回 ctx 错误。
290	func (e *Engine) runWithRetry(ctx context.Context, policy RetryPolicy, call func() error) (actionErr error, attempts int, err error) {
291		budget := normalizeRetry(policy)
292		for {
293			if err := ctx.Err(); err != nil {
294				return nil, attempts, err
295			}
296			attempts++
297			actionErr = call()
298			// 与基线一致：动作返回后先看外层 context，已取消则即使动作报告成功
299			// 也不确认该动作——结果可能已在下游生效，由同身份重入依赖动作幂等收敛。
300			if err := ctx.Err(); err != nil {
301				return nil, attempts, err
302			}
303			if actionErr == nil {
304				return nil, attempts, nil
305			}
306			if attempts >= budget.maxAttempts {
307				return actionErr, attempts, nil
308			}
309			// 仍有剩余次数：等待指定时长后再次调用同一动作，等待响应 context。
310			if budget.wait > 0 {
311				t := time.NewTimer(budget.wait)
312				select {
313				case <-ctx.Done():
314					t.Stop()
315					return nil, attempts, ctx.Err()
316				case <-t.C:
317				}
318			}
319		}
320	}
321	
322	// advanceCompensation 逆序补偿下一个已确认成功的步骤。
323	// 返回 done=true 表示已无待补偿步骤，调用方应把执行收束为 failed 终态。
324	// 补偿动作返回错误时，执行在同一事务中固定为 compensation_failed 终态。
325	func (e *Engine) advanceCompensation(ctx context.Context, def Definition, req ExecutionRequest, st *ExecutionState) (bool, error) {
326		idx := -1
327		for i := len(st.Steps) - 1; i >= 0; i-- {
328			if st.Steps[i].Status == StepResultSucceeded {
329				idx = i
330				break
331			}
332		}
333		if idx < 0 {
334			return true, nil
335		}
336		step := def.Steps[idx]
337	
338		// 未配置补偿动作的步骤视为补偿成功，不计数、不记录补偿时间。
339		var compErr error
340		var attempts int
341		var compensatedAt time.Time
342		if step.Compensate != nil {
343			// CompensationAttempts 记录本阶段（含预算内重试）补偿的实际调用次数，
344			// 成功或预算耗尽后随状态一次提交；中间失败不留计数、不追加事件。
345			var callErr error
346			compErr, attempts, callErr = e.runWithRetry(ctx, step.CompensateRetry, func() error {
347				return step.Compensate(ctx, execView{state: st, payload: req.Payload})
348			})
349			if callErr != nil {
350				return false, callErr
351			}
352			compensatedAt = e.now()
353			st.Steps[idx].CompensationAttempts = attempts
354		}
355	
356		err := e.store.Commit(ctx, req.BusinessKey, req.IdempotencyKey, func(tx Tx) error {
357			cur := tx.State()
358			if cur == nil || cur.Terminal() {
359				return nil
360			}
361			cs := &cur.Steps[idx]
362			if step.Compensate != nil {
363				cs.CompensationAttempts = attempts
364				cs.CompensatedAt = compensatedAt
365			}
366	
367			if compErr == nil {
368				cs.Status = StepResultCompensated
369				cs.LastError = ""
370				cur.Status = StatusCompensating
371				tx.AppendEvent(EventStepCompensated, EventPayload{
372					SagaName:       def.Name,
373					IdempotencyKey: req.IdempotencyKey,
374					Step:           step.Name,
375					Status:         StatusCompensating,
376				})
377				return nil
378			}
379	
380			errMsg := compErr.Error()
381			cs.Status = StepResultCompensationFailed
382			cs.LastError = errMsg
383			cur.FailedCompensationStep = step.Name
384			cur.CompensationError = errMsg
385			cur.Status = StatusCompensationFailed
386			tx.AppendEvent(EventStepCompensationFailed, EventPayload{
387				SagaName:       def.Name,
388				IdempotencyKey: req.IdempotencyKey,
389				Step:           step.Name,
390				Status:         StatusCompensationFailed,
391				Reason:         errMsg,
392				Attempt:        cs.CompensationAttempts,
393			})
394			tx.AppendEvent(EventCompensationFailed, EventPayload{
395				SagaName:       def.Name,
396				IdempotencyKey: req.IdempotencyKey,
397				Step:           step.Name,
398				Status:         StatusCompensationFailed,
399				Reason:         errMsg,
400			})
401			return nil
402		})
403		if err != nil {
404			return false, err
405		}
406		return false, nil
407	}
408	
409	// finishFailed 在补偿全部完成后把执行收束为 failed 终态并返回结果。
410	func (e *Engine) finishFailed(ctx context.Context, req ExecutionRequest) (Result, error) {
411		err := e.store.Commit(ctx, req.BusinessKey, req.IdempotencyKey, func(tx Tx) error {
412			cur := tx.State()
413			if cur == nil || cur.Terminal() {
414				return nil
415			}
416			cur.Status = StatusFailed
417			tx.AppendEvent(EventExecutionFailed, EventPayload{
418				SagaName:       cur.SagaName,
419				IdempotencyKey: req.IdempotencyKey,
420				Status:         StatusFailed,
421				Step:           cur.FailedStep,
422				Reason:         cur.FailureReason,
423			})
424			return nil
425		})
426		if err != nil {
427			return Result{}, err
428		}
429		snap, err := e.store.LoadSnapshot(ctx, req.BusinessKey, req.IdempotencyKey)
430		if err != nil {
431			return Result{}, err
432		}
433		return toResult(snap.State), nil
434	}
435	
436	func succeededNames(st *ExecutionState) []string {
437		var names []string
438		for _, s := range st.Steps {
439			if s.Status == StepResultSucceeded {
440				names = append(names, s.Name)
441			}
442		}
443		return names
444	}
445	
446	func stepEvent(def Definition, req ExecutionRequest, step, status string, succeeded []string) EventPayload {
447		return EventPayload{
448			SagaName:       def.Name,
449			IdempotencyKey: req.IdempotencyKey,
450			Step:           step,
451			Status:         status,
452			SucceededSteps: succeeded,
453		}
454	}
455	
456	func toResult(st *ExecutionState) Result {
457		outcomes := make([]StepOutcome, len(st.Steps))
458		for i, s := range st.Steps {
459			r := s.Status
460			if r == "" {
461				r = StepResultPending
462			}
463			outcomes[i] = StepOutcome{
464				Name:                 s.Name,
465				Result:               r,
466				Attempts:             s.Attempts,
467				CompensationAttempts: s.CompensationAttempts,
468				Error:                s.LastError,
469				StartedAt:            s.StartedAt,
470				FinishedAt:           s.FinishedAt,
471			}
472		}
473		return Result{
474			BusinessKey:            st.BusinessKey,
475			SagaName:               st.SagaName,
476			IdempotencyKey:         st.IdempotencyKey,
477			Status:                 st.Status,
478			FailureReason:          st.FailureReason,
479			CompensationError:      st.CompensationError,
480			FailedStep:             st.FailedStep,
481			FailedCompensationStep: st.FailedCompensationStep,
482			Steps:                  outcomes,
483			Terminal:               st.Terminal(),
484		}
485	}
486	
487	// GetResult 查询某执行身份的当前结果，不执行任何动作。
488	// 未知执行身份（或 sagaName 与该执行的定义名不符）返回 ErrExecutionNotFound。
489	func (e *Engine) GetResult(ctx context.Context, sagaName, businessKey, idempotencyKey string) (Result, error) {
490		if strings.TrimSpace(sagaName) == "" || strings.TrimSpace(businessKey) == "" || strings.TrimSpace(idempotencyKey) == "" {
491			return Result{}, ErrInvalidDefinition
492		}
493		snap, err := e.store.LoadSnapshot(ctx, businessKey, idempotencyKey)
494		if err != nil {
495			return Result{}, err
496		}
497		if snap.State == nil || snap.State.SagaName != sagaName {
498			return Result{}, ErrExecutionNotFound
499		}
500		return toResult(snap.State), nil
501	}
502

